import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { supabase } from '../supabaseClient';

function Universe() {
  const canvasRef = useRef(null);
  useEffect(() => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    let animId;
    const W = () => window.innerWidth;
    const H = () => window.innerHeight;
    canvas.width = W(); canvas.height = H();
    window.addEventListener('resize', () => { canvas.width = W(); canvas.height = H(); });
    const stars = Array.from({ length: 200 }, () => ({
      x: Math.random() * W(), y: Math.random() * H(),
      r: Math.random() * 1.2 + 0.1,
      o: Math.random() * 0.5 + 0.05,
      phase: Math.random() * Math.PI * 2,
      speed: Math.random() * 0.006 + 0.002,
    }));
    let t = 0;
    const draw = () => {
      ctx.clearRect(0, 0, W(), H());
      stars.forEach(s => {
        const pulse = s.o + Math.sin(t * s.speed + s.phase) * 0.15;
        ctx.beginPath(); ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(210,200,255,${pulse})`; ctx.fill();
      });
      t++; animId = requestAnimationFrame(draw);
    };
    draw();
    return () => cancelAnimationFrame(animId);
  }, []);
  return <canvas ref={canvasRef} style={{ position: 'fixed', inset: 0, zIndex: 0, pointerEvents: 'none' }} />;
}

export default function Dashboard() {
  const navigate = useNavigate();
  const [memorias, setMemorias] = useState([]);
  const [nome, setNome] = useState('');
  const [editandoNome, setEditandoNome] = useState(false);
  const [nomeTemp, setNomeTemp] = useState('');
  const [loaded, setLoaded] = useState(false);
  const [hovChat, setHovChat] = useState(false);
  const [hovMem, setHovMem] = useState(false);

  useEffect(() => {
    const carregar = async () => {
      const { data: { user } } = await supabase.auth.getUser();
      const { data: perfil } = await supabase.from('perfis').select('nome').eq('user_id', user.id).single();
      setNome(perfil?.nome || user.email.split('@')[0]);
      const { data } = await supabase.from('memorias').select('*').eq('user_id', user.id).order('created_at', { ascending: false });
      setMemorias(data || []);
      setTimeout(() => setLoaded(true), 100);
    };
    carregar();
  }, []);

  const salvarNome = async () => {
    if (!nomeTemp.trim()) return;
    const { data: { user } } = await supabase.auth.getUser();
    await supabase.from('perfis').upsert({ user_id: user.id, nome: nomeTemp });
    setNome(nomeTemp);
    setEditandoNome(false);
  };

  const totalPalavras = memorias.reduce((acc, m) => acc + (m.resposta?.split(' ').length || 0), 0);
  const diasAtivo = memorias.length > 0
    ? Math.ceil((new Date() - new Date(memorias[memorias.length - 1].created_at)) / (1000 * 60 * 60 * 24))
    : 0;

  const formatData = (str) => new Date(str).toLocaleDateString('pt-BR', { day: '2-digit', month: 'short', year: 'numeric' });

  return (
    <div style={{ minHeight: '100vh', background: '#030108', color: 'white', fontFamily: 'sans-serif' }}>
      <Universe />
      <div style={{ position: 'fixed', inset: 0, background: 'radial-gradient(ellipse 100% 60% at 50% 0%, rgba(80,20,180,0.15) 0%, transparent 60%)', zIndex: 1, pointerEvents: 'none' }} />
      <div style={{ position: 'fixed', inset: 0, background: 'radial-gradient(ellipse 60% 40% at 90% 90%, rgba(20,50,150,0.1) 0%, transparent 60%)', zIndex: 1, pointerEvents: 'none' }} />

      {/* Header */}
      <header style={{
        position: 'sticky', top: 0, zIndex: 200,
        padding: '22px 52px', display: 'flex', justifyContent: 'space-between', alignItems: 'center',
        backdropFilter: 'blur(30px)', background: 'rgba(3,1,8,0.7)',
        borderBottom: '1px solid rgba(255,255,255,0.04)',
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <svg width="18" height="18" viewBox="0 0 22 22" fill="none">
            <circle cx="11" cy="11" r="4" fill="url(#dg)" />
            <circle cx="11" cy="11" r="8" stroke="url(#dg2)" strokeWidth="0.6" strokeDasharray="2 3" />
            <defs>
              <radialGradient id="dg" cx="35%" cy="35%"><stop stopColor="#e9d5ff" /><stop offset="1" stopColor="#7c3aed" /></radialGradient>
              <linearGradient id="dg2" x1="0" y1="0" x2="22" y2="22"><stop stopColor="#c084fc" stopOpacity="0.6" /><stop offset="1" stopColor="#818cf8" stopOpacity="0.3" /></linearGradient>
            </defs>
          </svg>
          <span style={{ fontFamily: '"Palatino Linotype", Palatino, serif', fontSize: '0.9rem', letterSpacing: '5px', opacity: 0.7 }}>EVERLY</span>
        </div>
        <button onClick={async () => await supabase.auth.signOut()} style={{
          background: 'transparent', border: '1px solid rgba(255,255,255,0.08)',
          color: 'rgba(255,255,255,0.25)', padding: '7px 20px', borderRadius: '20px',
          cursor: 'pointer', fontSize: '0.75rem', letterSpacing: '1.5px',
          transition: 'all 0.3s',
        }}
          onMouseEnter={e => { e.currentTarget.style.borderColor = 'rgba(255,255,255,0.2)'; e.currentTarget.style.color = 'rgba(255,255,255,0.5)'; }}
          onMouseLeave={e => { e.currentTarget.style.borderColor = 'rgba(255,255,255,0.08)'; e.currentTarget.style.color = 'rgba(255,255,255,0.25)'; }}
        >SAIR</button>
      </header>

      <main style={{
        maxWidth: '860px', margin: '0 auto', padding: '70px 30px 120px',
        position: 'relative', zIndex: 10,
        opacity: loaded ? 1 : 0, transform: loaded ? 'none' : 'translateY(30px)',
        transition: 'opacity 1.4s ease, transform 1.4s ease',
      }}>

        {/* Hero greeting */}
        <div style={{ marginBottom: '70px' }}>
          <p style={{ fontSize: '0.68rem', letterSpacing: '4px', color: 'rgba(192,132,252,0.4)', textTransform: 'uppercase', marginBottom: '20px' }}>
            Seu universo pessoal
          </p>

          {editandoNome ? (
            <div style={{ display: 'flex', alignItems: 'flex-end', gap: '16px', marginBottom: '12px' }}>
              <input
                value={nomeTemp}
                onChange={e => setNomeTemp(e.target.value)}
                onKeyPress={e => e.key === 'Enter' && salvarNome()}
                autoFocus
                placeholder="Seu nome"
                style={{
                  fontFamily: '"Palatino Linotype", Palatino, serif',
                  fontSize: 'clamp(2.2rem, 6vw, 4rem)',
                  fontWeight: '400', background: 'transparent',
                  border: 'none', borderBottom: '1px solid rgba(124,58,237,0.4)',
                  color: 'white', outline: 'none', paddingBottom: '4px',
                  width: '100%', maxWidth: '500px',
                }}
              />
              <button onClick={salvarNome} style={{
                background: 'linear-gradient(135deg, rgba(124,58,237,0.8), rgba(79,70,229,0.8))',
                border: 'none', color: 'white', padding: '10px 24px',
                borderRadius: '20px', cursor: 'pointer', fontSize: '0.78rem',
                letterSpacing: '1px', marginBottom: '6px', flexShrink: 0,
              }}>SALVAR</button>
            </div>
          ) : (
            <div style={{ display: 'flex', alignItems: 'center', gap: '16px', marginBottom: '12px', flexWrap: 'wrap' }}>
              <h1 style={{
                fontFamily: '"Palatino Linotype", Palatino, serif',
                fontSize: 'clamp(2.2rem, 6vw, 4rem)',
                fontWeight: '400', lineHeight: 1.1,
                background: 'linear-gradient(135deg, #ffffff 0%, rgba(192,132,252,0.9) 60%, rgba(129,140,248,0.8) 100%)',
                WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent', backgroundClip: 'text',
                margin: 0,
              }}>{nome}</h1>
              <button onClick={() => { setNomeTemp(nome); setEditandoNome(true); }} style={{
                background: 'rgba(255,255,255,0.03)',
                border: '1px solid rgba(255,255,255,0.08)',
                color: 'rgba(255,255,255,0.25)', width: '32px', height: '32px',
                borderRadius: '50%', cursor: 'pointer', fontSize: '0.85rem',
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                transition: 'all 0.3s', flexShrink: 0,
              }}
                onMouseEnter={e => { e.currentTarget.style.borderColor = 'rgba(192,132,252,0.3)'; e.currentTarget.style.color = 'rgba(192,132,252,0.6)'; }}
                onMouseLeave={e => { e.currentTarget.style.borderColor = 'rgba(255,255,255,0.08)'; e.currentTarget.style.color = 'rgba(255,255,255,0.25)'; }}
              >✎</button>
            </div>
          )}

          <p style={{
            fontFamily: '"Palatino Linotype", Palatino, serif',
            fontSize: '1.1rem', fontStyle: 'italic',
            color: 'rgba(255,255,255,0.22)', lineHeight: 1.8,
          }}>
            {memorias.length === 0 ? 'Sua história começa agora.' : `${memorias.length} ${memorias.length === 1 ? 'memória preservada para a eternidade.' : 'memórias preservadas para a eternidade.'}`}
          </p>
        </div>

        {/* Stats */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '12px', marginBottom: '50px' }}>
          {[
            { num: memorias.length, label: 'Memórias' },
            { num: totalPalavras.toLocaleString(), label: 'Palavras' },
            { num: diasAtivo > 0 ? diasAtivo : '—', label: 'Dias ativos' },
          ].map((s, i) => (
            <div key={i} style={{
              background: 'rgba(255,255,255,0.015)',
              border: '1px solid rgba(255,255,255,0.05)',
              borderRadius: '18px', padding: '28px 24px', textAlign: 'center',
              position: 'relative', overflow: 'hidden',
            }}>
              <div style={{
                position: 'absolute', top: 0, left: 0, right: 0, height: '1px',
                background: 'linear-gradient(90deg, transparent, rgba(192,132,252,0.3), transparent)',
              }} />
              <span style={{
                display: 'block', fontSize: '2.2rem',
                fontFamily: '"Palatino Linotype", Palatino, serif', fontWeight: '400',
                background: 'linear-gradient(135deg, #e9d5ff, #818cf8)',
                WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent', backgroundClip: 'text',
                marginBottom: '6px',
              }}>{s.num}</span>
              <span style={{ fontSize: '0.68rem', color: 'rgba(255,255,255,0.2)', letterSpacing: '2px', textTransform: 'uppercase' }}>{s.label}</span>
            </div>
          ))}
        </div>

        {/* Action cards */}
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px', marginBottom: '70px' }}>
          <button
            onClick={() => navigate('/chat')}
            onMouseEnter={() => setHovChat(true)}
            onMouseLeave={() => setHovChat(false)}
            style={{
              background: hovChat
                ? 'radial-gradient(ellipse at top left, rgba(124,58,237,0.25), rgba(3,1,8,0.95))'
                : 'radial-gradient(ellipse at top left, rgba(124,58,237,0.1), rgba(3,1,8,0.95))',
              border: `1px solid ${hovChat ? 'rgba(192,132,252,0.3)' : 'rgba(255,255,255,0.06)'}`,
              borderRadius: '20px', padding: '32px 28px', cursor: 'pointer',
              textAlign: 'left', transition: 'all 0.4s',
              boxShadow: hovChat ? '0 0 60px rgba(124,58,237,0.15)' : 'none',
              position: 'relative', overflow: 'hidden',
            }}
          >
            {hovChat && <div style={{ position: 'absolute', top: 0, left: 0, right: 0, height: '1px', background: 'linear-gradient(90deg, transparent, rgba(192,132,252,0.5), transparent)' }} />}
            <div style={{ fontSize: '1.8rem', marginBottom: '16px', display: 'block' }}>◎</div>
            <span style={{ display: 'block', fontSize: '0.68rem', color: 'rgba(192,132,252,0.5)', letterSpacing: '2px', textTransform: 'uppercase', marginBottom: '8px' }}>Iniciar</span>
            <span style={{ display: 'block', fontFamily: '"Palatino Linotype", Palatino, serif', fontSize: '1.2rem', color: 'rgba(255,255,255,0.85)', fontWeight: '400' }}>Conversar com meu eu</span>
            <span style={{ display: 'block', fontSize: '0.82rem', color: 'rgba(255,255,255,0.25)', marginTop: '10px', lineHeight: 1.6 }}>Dialogue com seu eu digital através da IA</span>
          </button>

          <button
            onClick={() => navigate('/onboarding')}
            onMouseEnter={() => setHovMem(true)}
            onMouseLeave={() => setHovMem(false)}
            style={{
              background: hovMem
                ? 'radial-gradient(ellipse at top left, rgba(40,80,180,0.2), rgba(3,1,8,0.95))'
                : 'radial-gradient(ellipse at top left, rgba(40,80,180,0.06), rgba(3,1,8,0.95))',
              border: `1px solid ${hovMem ? 'rgba(129,140,248,0.25)' : 'rgba(255,255,255,0.06)'}`,
              borderRadius: '20px', padding: '32px 28px', cursor: 'pointer',
              textAlign: 'left', transition: 'all 0.4s',
              position: 'relative', overflow: 'hidden',
            }}
          >
            {hovMem && <div style={{ position: 'absolute', top: 0, left: 0, right: 0, height: '1px', background: 'linear-gradient(90deg, transparent, rgba(129,140,248,0.4), transparent)' }} />}
            <div style={{ fontSize: '1.8rem', marginBottom: '16px', display: 'block' }}>◇</div>
            <span style={{ display: 'block', fontSize: '0.68rem', color: 'rgba(129,140,248,0.5)', letterSpacing: '2px', textTransform: 'uppercase', marginBottom: '8px' }}>Registrar</span>
            <span style={{ display: 'block', fontFamily: '"Palatino Linotype", Palatino, serif', fontSize: '1.2rem', color: 'rgba(255,255,255,0.85)', fontWeight: '400' }}>Nova memória</span>
            <span style={{ display: 'block', fontSize: '0.82rem', color: 'rgba(255,255,255,0.25)', marginTop: '10px', lineHeight: 1.6 }}>Adicione histórias e momentos à sua coleção</span>
          </button>
        </div>

        {/* Memories */}
        <div style={{ marginBottom: '20px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <p style={{ fontSize: '0.68rem', color: 'rgba(255,255,255,0.18)', letterSpacing: '3px', textTransform: 'uppercase' }}>Arquivo de memórias</p>
          <p style={{ fontSize: '0.68rem', color: 'rgba(255,255,255,0.12)', letterSpacing: '1px' }}>{memorias.length} registros</p>
        </div>

        {memorias.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '80px 0', border: '1px dashed rgba(255,255,255,0.06)', borderRadius: '20px' }}>
            <p style={{ fontFamily: '"Palatino Linotype", Palatino, serif', fontStyle: 'italic', fontSize: '1.1rem', color: 'rgba(255,255,255,0.15)', lineHeight: 1.8 }}>
              Nenhuma memória ainda.<br />Comece contando sua história.
            </p>
            <button onClick={() => navigate('/onboarding')} style={{
              marginTop: '24px', background: 'transparent',
              border: '1px solid rgba(192,132,252,0.2)', color: 'rgba(192,132,252,0.5)',
              padding: '10px 28px', borderRadius: '20px', cursor: 'pointer',
              fontSize: '0.78rem', letterSpacing: '1.5px',
            }}>ADICIONAR PRIMEIRA MEMÓRIA</button>
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
            {memorias.map((m, i) => (
              <div key={i} style={{
                background: 'rgba(255,255,255,0.015)',
                border: '1px solid rgba(255,255,255,0.05)',
                borderLeft: '2px solid rgba(124,58,237,0.25)',
                borderRadius: '16px', padding: '26px 30px',
                transition: 'all 0.3s', position: 'relative', overflow: 'hidden',
              }}
                onMouseEnter={e => { e.currentTarget.style.borderLeftColor = 'rgba(192,132,252,0.5)'; e.currentTarget.style.background = 'rgba(255,255,255,0.025)'; }}
                onMouseLeave={e => { e.currentTarget.style.borderLeftColor = 'rgba(124,58,237,0.25)'; e.currentTarget.style.background = 'rgba(255,255,255,0.015)'; }}
              >
                <p style={{ fontSize: '0.68rem', color: 'rgba(192,132,252,0.35)', letterSpacing: '1.5px', textTransform: 'uppercase', marginBottom: '12px' }}>{m.pergunta}</p>
                <p style={{ fontFamily: '"Palatino Linotype", Palatino, serif', fontSize: '0.98rem', color: 'rgba(255,255,255,0.62)', lineHeight: 1.9 }}>{m.resposta}</p>
                <p style={{ fontSize: '0.68rem', color: 'rgba(255,255,255,0.12)', marginTop: '14px', letterSpacing: '0.5px' }}>{formatData(m.created_at)}</p>
              </div>
            ))}
          </div>
        )}
      </main>
    </div>
  );
}
